"""Compact graph snapshot for the Cloudflare Worker.

The local API still calls :func:`tcmkb_graph.draft.materialize` on the knowledge
tree. The Worker cannot ship that tree (lecture JSONL is tens of megabytes, and
most of it is mention lists the graph never returns). ``build_snapshot`` runs
the same function, keeps candidate edges, held rows, the lexicon index, and one
first-mention cite per lexicon id.

``load_snapshot`` rebuilds a :class:`~tcmkb_graph.draft.Materialization` and
re-validates every lecture edge with :class:`~tcmkb_graph.models.CandidateEdge`.
That model only allows ``review_status='candidate'``, so editing the file cannot
promote an edge to ``approved``.
"""
from __future__ import annotations

import json
from pathlib import Path

from pydantic import ValidationError

from tcmkb_graph.draft import Materialization, materialize
from tcmkb_graph.lexicon_index import Ent
from tcmkb_graph.models import CandidateEdge, HeldKP
from tcmkb_graph.subgraph import index_mentions

SNAPSHOT_VERSION = 1


def build_snapshot(root: Path) -> dict:
    """Same edges and held rows as ``materialize(root)``, plus mentions and lexicon ids."""
    root = Path(root)
    mat = materialize(root)
    mentions = {
        eid: cite
        for eid, cite in index_mentions(mat.knowledge_root).items()
        if eid in mat.index
    }
    return {
        "version": SNAPSHOT_VERSION,
        "edges": mat.edges,
        "held": mat.held,
        "index": _index_records(mat.index),
        "mentions": mentions,
    }


def write_snapshot(path: Path, root: Path) -> dict:
    payload = build_snapshot(root)
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    path.write_text(text + "\n", encoding="utf-8")
    return payload


def write_embedded_module(snapshot_path: Path, module_path: Path) -> None:
    """Write a Python module the Worker imports, so the JSON is part of the script bundle."""
    text = Path(snapshot_path).read_text(encoding="utf-8")
    json.loads(text)
    quoted = json.dumps(text, ensure_ascii=False)
    module_path = Path(module_path)
    module_path.parent.mkdir(parents=True, exist_ok=True)
    module_path.write_text(
        '"""Generated by ``python -m tcmkb_graph snapshot --embed``. Do not edit."""\n'
        f"GRAPH_SNAPSHOT_JSON = {quoted}\n",
        encoding="utf-8",
    )


def load_snapshot(path: Path) -> Materialization:
    """Load a snapshot. Raises if an edge would not pass the candidate model."""
    path = Path(path)
    return loads_snapshot(path.read_text(encoding="utf-8"), origin=path.parent)


def loads_snapshot(text: str, *, origin: Path) -> Materialization:
    """Parse snapshot JSON. ``origin`` is stored as ``knowledge_root`` and is not scanned."""
    data = json.loads(text)
    version = data.get("version") if isinstance(data, dict) else None
    if not isinstance(data, dict) or version != SNAPSHOT_VERSION:
        raise ValueError(f"unsupported graph snapshot version: {version}")
    edges = [_validated_edge(raw) for raw in _as_list(data.get("edges"), "edges")]
    held = [_validated_held(raw) for raw in _as_list(data.get("held"), "held")]
    index = _load_index(_as_list(data.get("index"), "index"))
    mentions = data.get("mentions") or {}
    if not isinstance(mentions, dict):
        raise ValueError("graph snapshot mentions must be an object")
    return Materialization(
        edges=edges,
        held=held,
        index=index,
        knowledge_root=Path(origin),
        mentions={str(k): v for k, v in mentions.items() if isinstance(v, dict)},
    )


def _validated_edge(raw: object) -> dict:
    try:
        edge = CandidateEdge.model_validate(raw)
    except ValidationError as exc:
        kp = raw.get("kp_id") if isinstance(raw, dict) else None
        raise ValueError(f"graph snapshot edge {kp} rejected by the candidate gate") from exc
    return edge.model_dump(mode="json")


def _validated_held(raw: object) -> dict:
    try:
        row = HeldKP.model_validate(raw)
    except ValidationError as exc:
        kp = raw.get("kp_id") if isinstance(raw, dict) else None
        raise ValueError(f"graph snapshot held row {kp} is invalid") from exc
    return row.model_dump(mode="json")


def _index_records(index: dict[str, Ent]) -> list[dict]:
    rows: list[dict] = []
    for eid in sorted(index):
        ent = index[eid]
        rows.append({
            "id": ent.id,
            "term": ent.term,
            "category": ent.category,
            "relations": [[pred, obj] for pred, obj in ent.relations],
        })
    return rows


def _load_index(rows: list) -> dict[str, Ent]:
    out: dict[str, Ent] = {}
    for raw in rows:
        if not isinstance(raw, dict) or not raw.get("id"):
            raise ValueError("graph snapshot index row is missing id")
        eid = str(raw["id"])
        if eid in out:
            raise ValueError(f"duplicate lexicon id {eid}")
        rels: list[tuple[str, str]] = []
        for rel in raw.get("relations") or []:
            if not isinstance(rel, (list, tuple)) or len(rel) != 2:
                raise ValueError(f"bad relation on {eid}")
            rels.append((str(rel[0]), str(rel[1])))
        out[eid] = Ent(
            id=eid,
            term=str(raw.get("term") or eid),
            category=str(raw.get("category") or ""),
            relations=tuple(rels),
        )
    return out


def _as_list(value: object, name: str) -> list:
    if not isinstance(value, list):
        raise ValueError(f"graph snapshot {name} must be a list")
    return value
